    # (e.g. parameter-dependent roots that are real on a subdomain);
    # downstream code (e.g. the D-check in log_to_real) validates them.
    rs = roots(f)
    rs = {r: m for r, m in rs.items() if r.is_real is not False}

    try:
        num_roots = f.count_roots()
    except DomainError:
        return rs
    else:
        if len(rs) == num_roots:
            return rs
        else:
